export class ConfigError extends Error {
  constructor(message: string) {
    super(message);
    this.name = 'ConfigError';
  }
}

export function splitKey(key: string): string[] {
  const parts: string[] = [];
  let current = '';
  let inQuotes = false;
  let quoteChar = '';

  for (let i = 0; i < key.length; i++) {
    const char = key[i];

    if ((char === '"' || char === "'") && !inQuotes) {
      inQuotes = true;
      quoteChar = char;
    } else if (char === quoteChar && inQuotes) {
      inQuotes = false;
      quoteChar = '';
    } else if (char === '.' && !inQuotes) {
      parts.push(current);
      current = '';
    } else {
      current += char;
    }
  }

  parts.push(current);
  return parts;
}

interface PathSegment {
  key: string | number;
  isIndex: boolean;
}

function parseSegments(part: string): PathSegment[] {
  const segments: PathSegment[] = [];
  const bracketRegex = /\[(\d+)\]/g;
  const firstBracket = part.indexOf('[');

  if (firstBracket === -1) {
    segments.push({ key: part, isIndex: false });
    return segments;
  }

  const prop = part.slice(0, firstBracket);
  if (prop.length > 0) {
    segments.push({ key: prop, isIndex: false });
  }

  let match: RegExpExecArray | null;
  while ((match = bracketRegex.exec(part)) !== null) {
    segments.push({ key: parseInt(match[1], 10), isIndex: true });
  }

  return segments;
}

export function parseConfig(raw: Record<string, any>): Record<string, any> {
  const result: Record<string, any> = {};

  for (const [key, value] of Object.entries(raw)) {
    const parts = splitKey(key);
    const segments: PathSegment[] = [];
    for (const part of parts) {
      segments.push(...parseSegments(part));
    }

    if (segments.length === 0) {
      continue;
    }

    let current: any = result;

    for (let i = 0; i < segments.length - 1; i++) {
      const seg = segments[i];
      const nextSeg = segments[i + 1];

      if (current[seg.key] === undefined) {
        current[seg.key] = nextSeg.isIndex ? [] : {};
      }
      current = current[seg.key];
    }

    const lastSeg = segments[segments.length - 1];
    current[lastSeg.key] = value;
  }

  return result;
}

